mapper.select:
SELECT SYS_CD
     , SYS_CDNM
  FROM WMS.TB_COMM_CODE
 WHERE 1 = 1
   AND SYS_GRP_CD = #{ sysGrpCd }   -- 그룹 코드

   AND SRVC_CD = #{ srvcCd }


   AND SYS_ETC1 = #{ sysEtc1 }


   AND SYS_ETC2 = #{ sysEtc2 }


   AND SYS_ETC3 = #{ sysEtc3 }


   AND SYS_ETC4 = #{ sysEtc4 }


   AND SYS_ETC5 = #{ sysEtc5 }

   AND USE_YN     = 'Y'
 ORDER BY SYS_SORT_SEQ, SYS_CD
